TP.register({id:"lp4-g2",lp:4,grade:"2",mode:"baseline",nextGrade:"3rd grade",build(E){const F=E.F;const ICON=(name,size)=>(F.icon||F.pic2)(name,size);const FABLE="Deep snow covered the path to the pine woods. Hare wanted to visit her friend Badger. But the snow came up to her ears. She hopped and hopped and got nowhere. “I can do it myself,” she puffed. Then she sat down, tired and cold. Badger came along on wide snowshoes. “Hop behind me,” he said. “My shoes press the snow flat.” Hare followed in his tracks, and the walking was easy. Now they clear the path together after every storm.";const FOX="A red fox does not sleep all winter. It grows a thick coat of fur and a bushy tail. At night the fox curls up and wraps its tail over its nose like a scarf. When snow covers the field, the fox listens for mice moving under it. Then it jumps high and dives nose first into the snow to catch one. A fox can hear a mouse from many steps away.";const ICE="When the air gets very cold, the top of a pond turns to ice. The ice starts out thin and clear. It grows thicker on each cold night. Under the ice the water does not freeze. Fish swim slowly near the bottom. Frogs rest in the mud and do not eat all winter. In spring the air warms up and the ice melts. The pond is open water again.";const WORDS=["slide","mitt","steep","glow","spoon","snowball","refill","coldest","could","again","shime","floot"];const passage=(title,text)=>`<h3 style="margin:14px 0 4px;color:var(--sea)">${title}</h3><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${text}</p>`;const lookBack=(label,text)=>`<details class="look-back" open><summary>Look back at ${label}</summary><p class="passage" style="font-size:1.45rem">${text}</p></details>`;const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const INK=window.TP_ICON_INK||"#6B4A3C";function pile(n,seed){const cols=Math.min(n,n>12?8:6),rows=Math.ceil(n/cols),c=48;let x=seed||5;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};let s=`<svg viewBox="0 0 ${cols*c+24} ${rows*c+24}" width="${cols*c+24}" role="img" aria-label="A pile of ${n} snowballs">`;s+=`<rect x="4" y="4" width="${cols*c+16}" height="${rows*c+16}" rx="20" fill="none" stroke="var(--line)" stroke-width="3"/>`;for(let i=0;i<n;i++){const cx=12+i%cols*c+c/2+(rnd()*12-6),cy=12+Math.floor(i/cols)*c+c/2+(rnd()*12-6);s+=`<circle cx="${cx.toFixed(0)}" cy="${cy.toFixed(0)}" r="17" fill="#F7FBFE" stroke="${INK}" stroke-width="2.6"/>`;s+=`<path d="M${(cx-9).toFixed(0)} ${(cy-3).toFixed(0)} q3 -9 11 -11" fill="none" stroke="#A8CBE4" stroke-width="3" stroke-linecap="round"/>`}return s+"</svg>"}function graphHtml(){const data=[["Sledding",6],["Skating",9],["Snowshoes",4],["Shoveling",E.state.shovel||0]];const rows=10,cell=32,x0=78,y0=34,bw=98,W=x0+data.length*bw+24,H=y0+10+rows*cell+46;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="Bar graph of what the village children did in the snow">`;s+=`<text x="${x0+data.length*bw/2}" y="22" text-anchor="middle" font-family="Andika,sans-serif" font-weight="700" font-size="21" fill="var(--ink)">What We Did in the Snow</text>`;for(let r=0;r<=rows;r++){const y=y0+10+(rows-r)*cell;s+=`<line x1="${x0}" y1="${y}" x2="${x0+data.length*bw}" y2="${y}" stroke="var(--line)" stroke-width="2"/>`;s+=`<text x="${x0-12}" y="${y}" text-anchor="end" dominant-baseline="central" font-size="16" fill="var(--ink)">${r}</text>`}data.forEach((d,i)=>{const bx=x0+i*bw+18;for(let r=0;r<rows;r++){const y=y0+10+(rows-r-1)*cell,filled=r<d[1];if(i===3)s+=`<rect class="sh" data-r="${r+1}" x="${bx}" y="${y}" width="62" height="${cell}" fill="${filled?"var(--gold)":"transparent"}" stroke="var(--sea)" stroke-dasharray="${filled?"0":"4 4"}" stroke-width="2" style="cursor:pointer"/>`;else if(filled)s+=`<rect x="${bx}" y="${y}" width="62" height="${cell}" fill="var(--sea)" stroke="var(--surface)" stroke-width="2"/>`}s+=`<text x="${bx+31}" y="${y0+10+rows*cell+26}" text-anchor="middle" font-size="16" font-weight="700" fill="var(--ink)">${d[0]}</text>`});return s+"</svg>"}const STOPS=[{id:1,title:"Mitten Word Flip",short:"Mitten Words",parts:[{std:["RF.2.3"],kind:"words",words:WORDS,n:12,dur:120,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading words with long and short vowels, vowel teams, a prefix, a suffix, and irregular spellings",key:["Read each word in order. shime and floot are made-up words: listen for the silent e long i sound and the oo team sound.","Watch for: long vs short vowel (slide, mitt), vowel teams (steep, glow, spoon), a compound word (snowball), prefix and suffix (refill, coldest), irregular words (could, again)."]}]},{id:2,title:"Read by the Fire",short:"By the Fire",parts:[{std:["RF.2.4"],kind:"read",n:81,label:"words read correctly",dur:120,dir:"Read the story out loud. Use your best reading voice.",desc:"an 81-word grade-level fable read aloud",html:()=>`<p class="passage">${FABLE}</p>`,key:["81 words. Mark each missed word and each self-correction on the passage in the record sheet.","Note pace and expression in your notes."]}]},{id:3,title:"Tracks in the Snow",short:"Tracks",parts:[{title:"Snow Story Questions",std:["RL.2.1"],dur:60,dir:"Look back at the story. Then answer each question out loud.",desc:"why and what questions about key details in a fable",html:()=>passage("Hare and Badger",FABLE),qs:["Why could Hare not get to the pine woods by herself?","What did Badger’s wide snowshoes do to the snow?"],key:["The snow was so deep that it reached her ears, so hopping got her nowhere. (RL.2.1)","They pressed it down flat, which made a path that was easy to walk on. (RL.2.1)"]},{title:"Retell and Lesson",std:["RL.2.2"],dur:60,dir:"Tell the story in your own words. Then answer out loud.",desc:"retelling a fable and telling its lesson",qs:["Tell me what happened in the story, from beginning to end.","What lesson does this story teach?"],key:["Retells in order: Hare set out to see Badger, the deep snow stopped her and she got tired, Badger came by on snowshoes and flattened a path, Hare walked behind him easily, and now the two friends clear the path together. (RL.2.2)","A job gets easier when you let a friend help, or friends should help each other. Accept any lesson the student ties to the story. (RL.2.2)"]}]},{id:4,title:"Cocoa and Pond Ice",short:"Cocoa Stop",parts:[{title:"Listen Up",std:["SL.2.2"],n:4,dur:90,read:FOX,dir:"Listen first. Then answer your teacher’s questions out loud.",desc:"recounting and describing key details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ICON("fox",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about a red fox in winter.</p>`,key:["What does the fox do with its tail at night? (curls up and wraps the tail over its nose like a scarf)","Describe how the fox catches a mouse when snow covers the field. (it listens for the mouse moving under the snow, jumps high, and dives in nose first)","Does the red fox sleep all winter? Tell what it does instead. (no, it stays awake and hunts; it grows a thick coat of fur)","Tell me two more things you learned about the red fox. (any two: thick coat of fur, bushy tail, it can hear a mouse from many steps away)"]},{title:"Listen and Answer",std:["RI.2.1"],dur:120,dir:"Read about pond ice. Then answer each question out loud.",desc:"what, where, when, and why questions about an informational text the student read",html:()=>passage("Pond Ice",ICE),qs:["What happens to the top of a pond when the air gets very cold?","Where do the fish swim while the pond is covered with ice?","When does the ice get thicker?","Why is the pond open water again in spring?"],key:["It turns to ice (RI.2.1)","Slowly, near the bottom, under the ice (RI.2.1)","On each cold night (RI.2.1)","The air warms up and the ice melts (RI.2.1)"]},{title:"Find It and Write It",std:["W.2.8"],dur:120,read:ICE,dir:"Listen while your teacher reads the Pond Ice text again. Then find your answers. Say the first two out loud. Write the last one on your paper and hold it up.",desc:"gathering information from a text on the page to answer questions",qs:["What do frogs do all winter? Find the part of the text that tells you.","Does the water under the ice freeze too?","Write one sentence to answer this question: Why can fish still live in a pond that is covered with ice? Use a fact from the text."],key:["They rest in the mud and do not eat all winter. The student should point to or read that sentence (W.2.8)","No. Under the ice the water does not freeze (W.2.8)","Writes a sentence built on the fact in the text, for example: The water under the ice does not freeze, so the fish can still swim near the bottom (W.2.8)"]}]},{id:5,title:"Snowball Fix-Up",short:"Fix-Up",parts:[{title:"Say It Right",std:["L.2.1"],dur:60,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular plural, irregular past tense, reflexive pronoun, making a sentence longer)",qs:["One goose, two ____.","Today I bring my sled. Yesterday I ____ my sled.","The kids pulled the sled all by ____.","Make it longer: “The fox ran.”"],key:["geese (L.2.1)","brought (L.2.1)","themselves (L.2.1)","Adds a detail and stays one complete sentence (The red fox ran across the frozen pond.) (L.2.1)"]},{title:"Write It Right",std:["L.2.2"],dur:85,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters, an apostrophe in a contraction, a comma in a letter greeting, spelling a vowel team word)",qs:["Fix this sentence: <b>the pond froze in january</b>","Write <b>did not</b> as one short word.","This is the start of a letter. Write it and add the missing mark: <b>Dear Badger</b>","Listen. Write the word your teacher says."],key:["The pond froze in January. (capital T, capital J, and a period) (L.2.2)","didn’t (with the apostrophe) (L.2.2)","Dear Badger, (comma after Badger) (L.2.2)","Say: “Coat. Zip up your coat.” The student writes coat (oa vowel team). (L.2.2)"]}]},{id:6,title:"Cabin Story Time",short:"Story Time",parts:[{std:["SL.2.4"],n:4,label:"checks met",dur:60,dir:"Tell your story out loud. Say what happened first, next, and last.",desc:"telling about an experience in order, with details, in clear complete sentences",html:()=>`<p class="big">Tell me about a day when the weather changed your plans. What did you do instead?</p>${pills("First","Next","Last")}`,key:["Tells events in order","Uses descriptive details","Speaks in complete sentences","Loud enough to hear"]}]},{id:7,title:"Village Numbers",short:"Numbers",parts:[{title:"Hundreds, Tens, Ones",std:["2.NBT.A.1"],dur:35,dir:"Look at the number on the cabin sign. Answer out loud.",desc:"telling how many hundreds, tens, and ones are in a three-digit number and the value of a digit",fig:()=>`<p class="huge">274</p>`,qs:["How many hundreds, how many tens, and how many ones?","What is the 2 worth?"],key:["2 hundreds, 7 tens, and 4 ones (2.NBT.A.1)","200, or 2 hundreds (2.NBT.A.1)"]},{title:"Write the Number",std:["2.NBT.A.3"],dur:35,dir:"Write your answers on your paper and hold it up.",desc:"writing a number in expanded form and writing a number from its name",qs:["Write 836 in expanded form.","I say five hundred three. Write it as a number."],key:["800 + 30 + 6 (2.NBT.A.3)","503 (2.NBT.A.3). Watch for an answer of 53 or 5003."]},{title:"Count the Snowy Miles",std:["2.NBT.A.2"],dur:35,dir:"Count out loud.",desc:"counting within 1000 and skip-counting by 5s",qs:["Count out loud from 697 to 713.","Skip count by 5s from 165 to 200."],key:["697, 698, 699, 700, 701 ... 713. Watch the jump past 699 (2.NBT.A.2)","165, 170, 175, 180, 185, 190, 195, 200 (2.NBT.A.2)"]}]},{id:8,title:"Snowflakes and Snowballs",short:"Snowflakes",parts:[{title:"Snowflake Array",std:["2.OA.C.4"],dur:30,dir:"Look at the snowflakes. Write your adding sentence on your paper and hold it up.",desc:"finding the total of an array and writing it as a sum of equal addends",fig:()=>`<div class="figure">${F.array(3,5,"snowflake")}</div>`,qs:["How many snowflakes in all?","Write an adding sentence for them."],key:["15 snowflakes (2.OA.C.4)","5 + 5 + 5 = 15 or 3 + 3 + 3 + 3 + 3 = 15 (2.OA.C.4)"]},{title:"Odd or Even",std:["2.OA.C.3"],dur:45,dir:"Count the snowballs in each pile. Answer out loud. Write the double on your paper.",desc:"telling odd from even and writing an even number as a double",fig:()=>`<div class="figure"><div>${pile(16,13)}<p class="fig-label">Pile A</p></div><div>${pile(11,41)}<p class="fig-label">Pile B</p></div></div>`,qs:["Is Pile A odd or even? Write it as a double.","Is Pile B odd or even?"],key:["Pile A has 16: even, 8 + 8 (2.OA.C.3)","Pile B has 11: odd (2.OA.C.3)"]}]},{id:9,title:"Sled Hill Problems",short:"Sled Hill",parts:[{title:"Sled Count",std:["2.OA.A.1"],dur:140,dir:"Read the problem. Write your number sentence on your paper and hold it up.",desc:"one-step compare, take-from and put-together word problems within 100 with the unknown in different places",qs:["In the morning there were 38 sleds on the hill. By the afternoon there were 65 sleds. How many more sleds came? Write a number sentence with a box for the number you do not know.","There were 54 cups of cocoa at the stand. 29 were sold. How many are left? Write a number sentence.","Noor made 26 snowballs. Theo made 17 more than Noor. How many did Theo make? Write a number sentence.","There are 52 logs in the woodpile. 19 are birch and the rest are pine. How many logs are pine? Write a number sentence."],key:["38 + □ = 65 or 65 - 38 = □; answer 27 sleds (2.OA.A.1)","54 - 29 = 25; answer 25 cups (2.OA.A.1)","26 + 17 = 43; answer 43 snowballs (2.OA.A.1)","52 - 19 = 33 or 19 + □ = 52; answer 33 pine logs (2.OA.A.1)"]},{title:"Two Steps",std:["2.OA.A.1"],dur:100,dir:"These problems have two steps. Read each one. Solve it on your paper and say your answer.",desc:"two-step addition and subtraction word problems within 100",qs:["Theo filled 23 cups of cocoa. Then he filled 18 more. People drank 30 of them. How many cups are left?","The village had 80 bags of sand for the icy paths. The crew used 25 bags on Monday and 36 bags on Tuesday. How many bags are left?"],key:["11 cups (23 + 18 = 41, then 41 - 30 = 11) (2.OA.A.1)","19 bags (80 - 25 = 55, then 55 - 36 = 19; or 25 + 36 = 61, then 80 - 61 = 19) (2.OA.A.1)"]},{title:"Big Snow Numbers",std:["2.NBT.B.7"],dur:110,dir:"Solve on your paper. Show your work and hold it up.",desc:"adding and subtracting three-digit numbers with regrouping and showing a strategy",qs:["Solve 475 + 318. Show how you did it.","Solve 600 - 245. Show how you did it.","Solve 268 + 374. Show how you did it."],key:["793, shows a place value strategy or a drawing (2.NBT.B.7)","355, regroups across the two zeros, or counts up from 245 (2.NBT.B.7)","642, regroups in both the ones and the tens (2.NBT.B.7)"]}]},{id:10,title:"Warming Hut",parts:[{title:"Cocoa Money",std:["2.MD.C.8"],dur:45,dir:"Look at the coins. Write each answer on your paper and hold it up.",desc:"a money word problem with quarters, a dime, and pennies using the cent sign",fig:()=>F.coins(["Q","Q","D","P","P"]),qs:["Tova has these coins in her mitten. How much money does she have? Write it with the right symbol.","A cup of cocoa at the warming hut costs 50¢. Tova buys one. How much money does she have left?"],key:["62¢ (2.MD.C.8). $0.62 is also correct, but 62¢ is the grade 2 target.","12¢ (2.MD.C.8)"]},{title:"Hut Clock",std:["2.MD.C.7"],dur:45,dir:"Look at the clock. Write the time on your paper. Then answer out loud.",desc:"telling time to five minutes with a.m. or p.m. and knowing a relationship of time",fig:()=>F.row(F.clock(3,25)),qs:["The warming hut closes at this time in the afternoon. Write the time. Is it a.m. or p.m.?","How many days are in a week?"],key:["3:25 p.m. (2.MD.C.7)","7 days (2.MD.C.7)"]}]},{id:11,title:"Snow Day Graph",short:"Snow Graph",parts:[{std:["2.MD.D.10"],n:3,dur:90,dir:"Tell your teacher how high to make the Shoveling bar. Then answer the questions out loud.",desc:"finishing a bar graph with four categories and solving compare and put-together problems from it",html:()=>`<p class="big" style="margin-top:0">3 kids helped with shoveling. Finish the graph.</p>`,render:()=>`<div class="figure">${graphHtml()}</div>`,bind:(root,ctx)=>root.querySelectorAll(".sh").forEach(r=>r.onclick=()=>{const v=+r.dataset.r;E.state.shovel=(E.state.shovel||0)===v?v-1:v;E.save();ctx.redraw()}),qs:["How many more kids chose skating than snowshoes?","How many kids chose sledding and shoveling together?"],key:["Shoveling bar filled to 3. Click the squares as the student tells you, or have them draw it on paper.","Skating (9) take away snowshoes (4) leaves 5 more","Sledding (6) plus shoveling (3) makes 9"]}]},{id:12,title:"Snowshoe Measure",short:"Measure",parts:[{title:"Measure It",std:["2.MD.A.1"],dur:45,dir:"Get a ruler and a book. Measure the book. Then answer out loud.",mats:["a ruler","a book"],desc:"measuring an object with a ruler and choosing the right measuring tool",fig:()=>F.row([F.ruler({length:6}),"Inches. Line the end of the book up with 0"]),qs:["Measure your book with a ruler. How long is it?","What tool would you use to measure how long a hallway is?"],key:["Lines the ruler up at 0 and gives a reasonable length with units (2.MD.A.1)","A measuring tape, a yardstick, or a meter stick (2.MD.A.1)"]},{title:"Shapes in the Village",std:["2.G.A.1"],dur:30,dir:"Draw on your paper and hold it up. Then answer out loud.",desc:"drawing and naming a six-sided shape and naming the faces of a cube",fig:()=>F.row([F.prism(1,1,1,{unit:84}),"An ice block"]),qs:["Draw a shape with 6 sides. What is it called?","The ice block is a cube. What shape is each face, and how many faces are there?"],key:["Hexagon (2.G.A.1)","Each face is a square, and there are 6 faces (2.G.A.1)"]}]},{id:13,title:"Write in the Cabin",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Letter to Hare",icon:"✉️",hint:"Tell Hare what you think"},std:["W.2.1"],n:4,label:"checks met",dur:210,dir:WRITE_DIR,desc:"an opinion letter about the fable",html:()=>`<p class="big">Write a letter to Hare. Should she have asked Badger for help sooner? Tell her why, using the story. Write 3 or 4 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Start with: Dear Hare</li><li>End with: Your friend and your name</li></ul>${lookBack("the story",FABLE)}`,key:["States an opinion (W.2.1)","Gives a reason from the story (W.2.1)","Uses a linking word like because or also (W.2.1)","Ends with a closing sentence (W.2.1)"]},{alt:{group:"write",key:"facts",label:"Pond Ice Facts",icon:"❄️",hint:"Teach about pond ice"},std:["W.2.2"],n:4,label:"checks met",dur:210,dir:WRITE_DIR,desc:"an informative piece about pond ice",html:()=>`<p class="big">Write about pond ice. Teach your reader 2 or more facts from Pond Ice. Write 3 or 4 sentences.</p>${lookBack("Pond Ice",ICE)}`,key:["Introduces the topic (W.2.2)","Gives 2 or more facts about pond ice (W.2.2)","The facts stay on the topic and are true to the Pond Ice text (W.2.2)","Ends with a closing sentence (W.2.2)"]},{alt:{group:"write",key:"story",label:"My Outside Job",icon:"👢",hint:"Tell about a job you did outside"},std:["W.2.3"],n:4,label:"checks met",dur:210,dir:WRITE_DIR,desc:"a narrative about a real experience",html:()=>`<p class="big">Think of a job you did outside, like sweeping, raking, washing something, carrying something heavy, or shoveling. What happened? Write a story about it. Write 3 or 4 sentences.</p>${pills("First","Next","Last")}`,key:["Tells about one event or a short set of events in order (W.2.3)","Includes details about actions, thoughts, or feelings (W.2.3)","Uses time words like first, next, then, or last (W.2.3)","Gives a sense of closure (W.2.3)"]}]},{id:14,title:"Three Pots on the Cabin Sill",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">Three pots of bean seeds were started indoors in the middle of winter and checked after four weeks.</p>
     <table class="bigTable"><tr><th>Pot</th><th>Where it sat and what it got</th><th>How tall it grew</th></tr>
     <tr><td>1</td><td>the sunny window, watered twice a week</td><td>18 centimeters, dark green</td></tr>
     <tr><td>2</td><td>the sunny window, never watered</td><td>2 centimeters, then dried up</td></tr>
     <tr><td>3</td><td>a closed cupboard, watered twice a week</td><td>11 centimeters, thin and yellow</td></tr></table>
     <div class="figure">${ICON("sprout",88)}${ICON("cabin",88)}</div>`,qs:["Which pot did best, and what did it get?","Pot 3 grew 11 centimeters in the dark. Why is it still worse off than pot 1?","You want to test only whether a bean needs water. Name two things you would keep the same, and name the one thing you would change."],key:["Pot 1, 18 centimeters and dark green. It got both sunlight and water.","It is thin and yellow. It used up what was stored in the seed to get tall, but with no sunlight it cannot make its own food and go green, so it will not keep going.","Keep the same: the same soil, the same pot, the same number of seeds, the same window. Change only one thing: one pot watered and one pot not watered. Changing two things is not a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it moves seeds",html:()=>`<p class="big">In winter the birds eat berries. The birds are in the village. The berries come off the hedge. The seeds inside go through the bird. They land somewhere else. It is far from the hedge. In spring some of them grow.</p>
     <div class="figure">${ICON("cardinal",88)}${ICON("tree",88)}</div>
     <p class="big">Draw a model you could really build from things in a cabin, such as a paper cone with a flap, that would take a seed in at one end, hold it while you walk across the room, and let it out at the other end.</p>`,qs:["Draw your model. Label where the seed goes in and where it comes out.","Which animal job does your model copy, and why does it matter that the seed comes out far from the hedge?"],key:["Any model with an opening to take the seed in, a space to hold it, and a way to let it out: a cone with a flap, a tube with a plug, a cup with a lid and a hole. The two labeled ends are what to look for.","It copies a bird that eats a berry in one place and leaves the seed somewhere else. Far away matters because a seed dropped right under the hedge would have to fight the hedge for sunlight and water, and a seed in open ground has room to grow."]}]},{id:15,title:"The Pond Edge and the Pine Woods",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">Two children looked for signs of living things in two places on the same cold afternoon.</p>
     <table class="bigTable"><tr><th>The frozen pond edge</th><th>The pine woods on the slope</th></tr>
     <tr><td>1 kind of reed sticking through the ice</td><td>3 kinds of pine and fir</td></tr>
     <tr><td>1 kind of moss on the wet stones</td><td>2 kinds of moss</td></tr>
     <tr><td>duck tracks in the snow</td><td>1 squirrel, deer tracks, 2 kinds of bird</td></tr>
     <tr><td></td><td>1 kind of fern under the snow</td></tr></table>
     <div class="figure">${ICON("pine",80)}${ICON("deer",80)}</div>`,qs:["How many kinds of living things or signs are on the pine woods list?","Which place has more different kinds in winter?","The pond edge is open and frozen and the woods are full of thick evergreen branches. Explain how that could make the two lists so different."],key:["9. Three pines and firs, two mosses, one squirrel, deer tracks, two birds and one fern.","the pine woods","The woods give shelter from the wind and snow, food in the cones, and branches to hide in, so many kinds of living thing can get through the winter there. The pond edge is frozen and open, so there is little food and no shelter. Listen for the link between what a place gives and what lives there."]}]},{id:16,title:"One Night, or Many Winters",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about the land around the village, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>the village road log</td><td>A bank of wet snow slid down over the lower road in one night and had to be dug out in the morning.</td></tr>
     <tr><td>a trail sign at the big split rock</td><td>Water got into a crack in this rock, froze, and pushed a little wider every winter. After many winters the rock split in two.</td></tr></table>`,qs:["Which note tells about a change that happened quickly?","Which note tells about a change that took many years?","Name one more change to the land that happens quickly, and one that happens slowly."],key:["The road log, the bank of snow sliding over the road in one night.","The trail sign, the rock split after many winters of freezing water.","Quick: a flood, a rockfall, a bank falling in, a tree pushed over in a storm. Slow: a stream cutting a valley, a hill wearing down, a cliff wearing back. The answer has to name a change to the land, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">In winter, the water around the village is easy to spot because so much of it is hard.</p>
     <div class="figure">${ICON("snowflake",80)}${ICON("drop",80)}${ICON("cloud",80)}</div>`,qs:["Name three places around this village where you would find water.","Most of the water on Earth is in the ocean and it is salty. Name a place near the village where the water is fresh instead.","Sort these four into solid water and liquid water: the ice on the pond, the stream under the bridge, the snow on the roof, the water in the kettle."],key:["Any three: the pond, the stream, the well, the snow on the roofs, icicles, clouds, under the ground.","The stream, the pond, the well, or melted snow. Fresh water is the kind people can drink.","Solid: the ice on the pond and the snow on the roof. Liquid: the stream and the water in the kettle."]}]},{id:17,title:"Holding the Path, and a Map of the Village",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things put in place to stop running water from washing the land away",html:()=>`<p class="big">When the snow melts, the water runs down the path to the pond and carries the dirt away, leaving holes. Two fixes were tried and the holes were counted at the end of the melt.</p>
     <table class="bigTable"><tr><th>What was on the path</th><th>Holes in the path after the melt</th></tr>
     <tr><td>bare dirt</td><td>11 holes</td></tr>
     <tr><td>a layer of gravel</td><td>1 hole</td></tr>
     <tr><td>flat planks laid end to end</td><td>4 holes, where water ran off the plank edges</td></tr></table>`,qs:["Which fix kept the path in the best shape?","How do you know, using the numbers in the chart?","The planks still got 4 holes. Looking at the chart, where did the water do the damage, and why?"],key:["the layer of gravel","There was only 1 hole with the gravel, 4 with the planks, and 11 with bare dirt. The reason must come from the numbers.","At the plank edges. The water could not soak through the planks, so it ran off the sides all in one place and dug holes there. The gravel let the water soak down between the stones instead."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the village. Put in the sled hill, the flat meadow, the pond, and the stream that runs out of it. Add a key that says which is which.</p>
     <div class="figure">${ICON("mountain",88)}${ICON("map",88)}${ICON("sled",88)}</div>`,qs:["Draw your model map with the hill, the flat meadow, the pond and the stream on it.","Show me your key. Which parts are land and which parts are water?","Is the pond a bigger body of water than the stream or a smaller one? Name one that is bigger than both."],key:["All four on the page and told apart by shape or color: the hill as a bump or as rings, the meadow left flat, the pond as a closed shape, the stream as a line running out of it.","Points to each part and reads the key. The key is what makes this a model and not just a picture.","A pond holds more water than a stream, though a stream can be longer. Bigger than both: a lake, a river, the ocean. Accept a well explained answer either way for the first half."]}]},{id:18,title:"Sorting the Warming Hut Basket",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">Four things out of the basket by the warming hut door, and what was noticed about each one.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What was noticed</th></tr>
     <tr><td>a mitten</td><td>wool</td><td>soft, bends easily, keeps a hand warm, soaks water up</td></tr>
     <tr><td>a boot</td><td>rubber</td><td>bends, stretches a little, keeps water out</td></tr>
     <tr><td>a shovel blade</td><td>metal</td><td>hard, shiny, cold to touch</td></tr>
     <tr><td>a lantern pane</td><td>glass</td><td>hard, smooth, you can see through it</td></tr></table>`,qs:["Sort the four items into a hard group and a group that bends.","Which one soaks water up, and which one keeps water out?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Hard: the metal shovel blade and the glass lantern pane. Bends: the wool mitten and the rubber boot.","The wool mitten soaks water up. The rubber boot keeps water out.","Any property that can be seen or felt and that really splits the four: see through or not, soft or hard, shiny or dull, warm or cold to touch. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">A draught comes in through the cabin window. Three materials were taped over the glass on three cold nights and the temperature inside was written down each morning.</p>
     <table class="bigTable"><tr><th>Material taped over the window</th><th>Inside by morning</th><th>Could you still see out</th></tr>
     <tr><td>nothing at all</td><td>8 degrees</td><td>yes</td></tr>
     <tr><td>a thin cotton sheet</td><td>10 degrees</td><td>no</td></tr>
     <tr><td>clear plastic sheet</td><td>14 degrees</td><td>yes</td></tr></table>`,qs:["Which material is best for the window?","Which two pieces of the chart make you sure?","The cotton sheet did keep the room 2 degrees warmer. Why would the family still take it down?"],key:["the clear plastic sheet","The room was 14 degrees with the plastic, which is warmer than the 10 degrees with cotton and the 8 degrees with nothing, and you could still see out through it. Both columns have to be used.","You cannot see out through it, so the room is dark and nobody can look at the weather or the hill. It keeps some heat in but it costs them the window."]}]},{id:19,title:"Taken Apart, Heated, Cooled",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">An old sled is in the shed. It is made of 2 long runners. It has 5 flat slats. It has 10 screws. Someone took all the screws out. They leaned the pieces against the wall.</p>
     <div class="figure">${ICON("sled",88)}${ICON("board",88)}</div>`,qs:["The sled is gone. Are the runners and slats gone too? What is against the wall?","Build something new in your head out of those 2 runners, 5 slats and 10 screws. What is it, and how do the pieces go together?"],key:["No. Both runners, all 5 slats and all 10 screws are still there. They are the same pieces, just not screwed together as a sled any more.","Any real thing from 2 long pieces and 5 flat ones: a bench, a shelf, a step, a sign, a small table, a bird feeder, a snow fence. Listen for how the pieces join, because that is the evidence the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened by the cabin stove on the same evening.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A handful of snow was put in a mug near the stove and turned into water.</td></tr>
     <tr><td>A slice of bread was left too long on the stove top and turned black and crumbly.</td></tr></table>
     <div class="figure">${ICON("snowflake",80)}${ICON("bread",80)}</div>`,qs:["Put the mug of water out on the step in the cold. What happens to it?","Put the black slice out on the step in the cold. Does it turn back into bread?","Which of the two changes can be undone, and what is your evidence?"],key:["It freezes into ice. Cooling undoes the melting, and warming it would melt it again.","No. It stays black and crumbly. Cold does not bring the bread back.","The snow and water change can be undone. The evidence is that the water freezes again when it is put out in the cold, and the burnt bread does not come back when it is cooled. Listen for the student using what happened, not just saying yes or no."]}]},{id:20,title:"The Firewood That Topples",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">The firewood is for the warming hut. It is stacked in a pile. The pile is beside the door. Every few days the pile leans. Then it slides. It spills logs out into the snow. Then the logs are wet and will not light. Someone has to stack them all over again.</p>`,qs:["What is the problem the village wants to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The woodpile slides apart and the logs fall into the snow and get wet. Naming the pile spilling, not the restacking, is the problem.","Any real question: how high is the pile, how long are the logs, is the ground flat, which side does it lean to, how much wood has to fit. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw something that would hold the firewood in a stack and off the wet snow. Think hard about its shape.</p>
     <div class="figure">${ICON("box",88)}${ICON("board",88)}</div>`,qs:["Draw your fix.","Tell me how the shape of what you drew holds the logs in."],key:["Any design that could really hold logs: a rack with two end posts, a three sided box, a frame with a floor off the ground, a roof over the top, a crate.","The shape is the part being checked. Something like: the two end posts stop the ends sliding out, the walls hold the sides in, the floor keeps the bottom logs off the snow, the roof keeps the snow off."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">Both racks were used for two weeks with the same amount of wood.</p>
     <table class="bigTable"><tr><th>Rack</th><th>Times the pile spilled</th><th>Logs too wet to light</th></tr>
     <tr><td>a box with a floor off the ground and a roof</td><td>0</td><td>0</td></tr>
     <tr><td>two end posts, no floor and no roof</td><td>1</td><td>9</td></tr></table>`,qs:["Which rack worked better?","How do you know? Use both columns."],key:["the box with a floor off the ground and a roof","The pile never spilled and no logs were too wet, while the other one spilled once and left 9 logs too wet to light. Both columns have to be used, not just the spilling."]}]},{id:21,title:"The Village Then and Now",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the village notice board.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>This morning the mail came up the valley in a truck with chains on its tyres.</td></tr>
     <tr><td>2</td><td>When the village was young, the mail came once a month on a horse sleigh.</td></tr>
     <tr><td>3</td><td>Yesterday the children cleared the pond for skating.</td></tr>
     <tr><td>4</td><td>Long before there were refrigerators, people here cut blocks of pond ice in winter and packed them in sawdust to keep food cold all summer.</td></tr></table>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Now make a timeline of your own life. Tell me four things that have happened to you, in the order they happened, starting with the earliest."],key:["Lines 2 and 4, the mail on a horse sleigh and cutting pond ice to keep food cold.","Lines 1 and 3, the mail truck this morning and clearing the pond yesterday.","Any four true events in the right order, such as: I was born, I learned to walk, I started school, I moved house, I learned to swim, I started this grade. The order is what is being checked, not the events themselves. Putting their own events in the order they happened is this standard’s third part. (HSS-2.1)"]}]},{id:22,title:"Where Things Are in the Village",short:"Village Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">The village, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ICON("pine",46)} pine woods</td><td>${ICON("sled",46)} sled hill</td><td>${ICON("mountain",46)} ridge</td></tr>
     <tr><th>B</th><td>${ICON("cabin",46)} cabins</td><td>${ICON("cocoa",46)} warming hut</td><td>${ICON("bridge",46)} stone bridge</td></tr>
     <tr><th>C</th><td>${ICON("skate",46)} pond</td><td>${ICON("lantern",46)} lane</td><td>${ICON("box",46)} wood store</td></tr></table>
     <p class="big">${ICON("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>`,qs:["Give the exact square the warming hut is in, using its letter and its number.","What is directly north of the warming hut?","Is the pond east or west of the wood store?","Which square is between the cabins and the stone bridge?"],key:["B2","the sled hill, in square A2","west. The pond is in C1 and the wood store is in C3, so the pond is to the left, which is west.","B2, the warming hut"]}]},{id:23,title:"Rules, Money and the Cocoa Stand",short:"Rules and Money",parts:[{std:["HSS-2.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling who makes rules at each level here, and how another country chooses a leader differently",html:()=>`<p class="big">Once a month the village holds a meeting in the hut and everyone there gets a vote.</p>
     <div class="figure">${ICON("flag",80)}${ICON("hands",80)}</div>`,qs:["At the village meeting, 14 people vote to clear the pond for skating and 6 vote to leave it. What happens, and why?","Who makes the laws for a whole state? One family, or the people the state votes for?","In some other countries the leader is a king or a queen who was born into the job. In our country, how do we get our leaders?"],key:["The pond is cleared. More people voted for it than against it, and that is how a vote is decided.","the people the state votes for. Accept: the state lawmakers, the legislature, with the governor leading the state.","We vote for them. Any answer that says the people choose their leaders by voting counts."]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the price list. Answer out loud.",desc:"telling goods from services, spending a set amount of money, and saying why people trade",html:()=>`<p class="big">The warming hut price list.</p>
     <table class="bigTable"><tr><th>What is on offer</th><th>Price</th></tr>
     <tr><td>a cup of cocoa</td><td>30 cents</td></tr>
     <tr><td>a bowl of soup</td><td>50 cents</td></tr>
     <tr><td>a wool mitten patch</td><td>15 cents</td></tr>
     <tr><td>someone to sharpen your skates</td><td>25 cents</td></tr></table>
     <div class="figure">${ICON("cocoa",72)}${ICON("soup",72)}${ICON("mitten",72)}</div>`,qs:["Three things on this list are goods and one is a service. Which one is the service, and how do you know?","You have 55 cents. Name two things you could buy with it, and say what you give up.","The village makes its own firewood but buys its flour from town. Why do people trade instead of making everything themselves?"],key:["Sharpening your skates. It is work someone does for you, not a thing you carry away.","Any pair at 55 cents or less: cocoa and the sharpening is 55 cents, cocoa and a patch is 45 cents, soup and a patch is 65 cents and is too much. The giving up is the part to listen for.","Because nobody can make everything. Each place makes what it can and trades for the rest. Accept: it saves time, you get what you cannot make where you live."]}]},{id:24,title:"Someone Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about him. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">Abraham Lincoln grew up in a log cabin. It had one room. It stood on the edge of the woods. His family had almost no books. So he borrowed any he could find. He read by the light of the fire. He did it after a long day of work. He kept teaching himself for years. He became a lawyer. Later he became president. He was the sixteenth president of the United States. At that time people could be bought and sold. They were sold as property. It happened in part of the country. Lincoln believed that was wrong. He worked to end it. He signed a paper. It began setting those people free. He kept the country together. Many wanted it split in two.</p>
     <div class="figure">${ICON("cabin",80)}${ICON("books",80)}</div>`,qs:["How did Abraham Lincoln learn so much as a boy?","Which word fits him best from what you read: determined, lazy, or unfair? Say why.","Name one way what he did made a difference to other people."],key:["He borrowed every book he could find and read by the firelight after work, and he kept teaching himself for years.","determined. Any reason taken from the text: he taught himself by firelight, he kept going for years with almost no books, he stood by what he believed was right.","He signed the paper that began setting people free who had been bought and sold, and he kept the country from splitting in two."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Long Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each long word out loud.",html:()=>`<div style="text-align:center">${["slippery","disappearing","remarkable"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["slippery (slip-per-y)","disappearing (dis-ap-pear-ing)","remarkable (re-mark-a-ble)"]},3:{id:"L3",title:"Level Up: Show the Lesson",std:["RL.3.2"],needs:["RL.2.2"],n:1,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.45rem">${FABLE}</p><p class="big">The lesson is that a hard job gets easier when a friend helps. Which parts of the story show that lesson?</p>`,key:["Names details that carry the lesson, such as Hare saying she can do it alone and then getting nowhere, Badger flattening the snow so the walking was easy, and the two of them clearing the path together at the end."]},9:{id:"L9",title:"Level Up: Two-Step Problem",std:["3.OA.D.8"],needs:["2.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The cabin has 4 shelves of cocoa mugs with 5 mugs on each shelf. 6 more mugs are in the sink. How many mugs are there in all?</p>`,key:["26 mugs (4 x 5 = 20, then 20 + 6 = 26)"]},10:{id:"L10",title:"Level Up: Clock Challenge",std:["3.MD.A.1"],needs:["2.MD.C.7"],n:2,dir:"Look at the clock. Answer out loud.",html:()=>`<div class="figure">${F.clock(11,17)}</div><ol class="qlist"><li>What time is it?</li><li>Skating starts at 1:45. It lasts 30 minutes. What time does it end?</li></ol>`,key:["11:17 (to the nearest minute)","2:15"]}};const PASSAGE_STD=["RL.2.1","RL.2.2","RI.2.1","RL.3.2","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let chartOn={},pvVal=["",""];function chartHtml(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${chartOn[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}const STARTERS={opinion:["I think ____.","One reason is ____.","Also, ____.","That is why ____."],facts:["Pond ice ____.","One fact is ____.","Another fact is ____.","Now you know ____."],story:["One day, ____.","First, ____.","Next, ____.","Last, ____.","I felt ____."]};const SENTSET={"W.2.1":"opinion","W.2.2":"facts","W.2.3":"story","W.2.8":"facts"};const SENTLAB={opinion:"If you are writing what you think:",facts:"If you are writing facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length){const k=parts[0]&&parts[0].alt&&parts[0].alt.key;sets.push(STARTERS[k]?k:"opinion")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}let tpsBlk=[0,0,0];function tpsMatSvg(h,t,o){return F.blocks(h,t,o)}function tpsBlkHtml(){const b=(k,t)=>`<button class="chip" data-tb="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${tpsBlk[0]+tpsBlk[1]+tpsBlk[2]?tpsMatSvg(tpsBlk[0],tpsBlk[1],tpsBlk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${tpsBlk[0]} hundreds, ${tpsBlk[1]} tens, and ${tpsBlk[2]} ones on the mat.</p>`}function tpsBlkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")tpsBlk=[0,0,0];else if(k==="to"){if(tpsBlk[2]>=10&&tpsBlk[1]<19){tpsBlk[2]-=10;tpsBlk[1]++}}else if(k==="th"){if(tpsBlk[1]>=10&&tpsBlk[0]<9){tpsBlk[1]-=10;tpsBlk[0]++}}else if(k==="bt"){if(tpsBlk[1]>=1&&tpsBlk[2]<=9){tpsBlk[1]--;tpsBlk[2]+=10}}else if(k==="bh"){if(tpsBlk[0]>=1&&tpsBlk[1]<=9){tpsBlk[0]--;tpsBlk[1]+=10}}else tpsBlk[i]=Math.max(0,Math.min(MAX[i],tpsBlk[i]+(k[1]==="+"?1:-1)))}let tpsNlStart="",tpsNlHops=[],tpsNlShown={};function tpsNlSvg(){if(tpsNlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+tpsNlStart];tpsNlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;tpsNlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+tpsNlStart||tpsNlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+tpsNlStart?"":`data-tv="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function tpsNlHtml(){const j=d=>`<button class="chip" data-tj="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="tpsNlStart" value="${tpsNlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-tj="u">Undo</button><button class="chip" data-tj="x">Clear</button></div><div class="tool-scroll" id="tpsNlBox" style="text-align:center">${tpsNlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function tpsNlBind(b,r){const box=()=>b.querySelectorAll("[data-tv]").forEach(g=>g.onclick=()=>{tpsNlShown[g.dataset.tv]=!tpsNlShown[g.dataset.tv];r()});const inp=b.querySelector("#tpsNlStart");inp.oninput=()=>{tpsNlStart=inp.value.replace(/[^0-9]/g,"");tpsNlShown={};b.querySelector("#tpsNlBox").innerHTML=tpsNlSvg();box()};b.querySelectorAll("[data-tj]").forEach(x=>x.onclick=()=>{const k=x.dataset.tj;if(k==="x"){tpsNlHops=[];tpsNlShown={}}else if(k==="u")tpsNlHops.pop();else if(tpsNlStart!==""&&tpsNlHops.length<10)tpsNlHops.push(+k);r()});box()}function tpsClockHtml(){return`<div style="text-align:center;margin:8px 0"><img alt="A clock face. The short red hour hand points to the 10. The long blue minute hand points to the 12. Big numbers 1 to 12 are the hours. Small labels around the edge count minutes by fives, from :00 to :55." src="data:image/webp;base64,${window.TP_IMG1.wp.clocklab}" style="width:340px;max-width:100%;height:auto"></div>`+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return `<div style="text-align:center"><img alt="An inch ruler from 0 to 6 with a pencil lined up at 0. The tip of the pencil is at 5 inches." src="data:image/webp;base64,${window.TP_IMG1.wp3.inchruler}" style="width:640px;max-width:100%;height:auto"></div>`+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:chartHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{chartOn[x.dataset.n]=!chartOn[x.dataset.n];r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},coins:{name:"Coin values",std:["2.MD.C.8"],html:()=>`<div class="figure" style="gap:18px;flex-wrap:wrap;align-items:flex-end">${[["Q","25¢"],["D","10¢"],["N","5¢"],["P","1¢"]].map(([k,v])=>`<span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${F.coin(k)}<b style="font-size:1.1rem">${v}</b></span>`).join("")}</div><p class="small" style="margin:8px 0 0">This chart gives the value of each coin. The student still does the adding and still writes the cent sign.</p>`},nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:tpsNlHtml,bind:tpsNlBind},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:tpsBlkHtml,bind:(b,r)=>b.querySelectorAll("[data-tb]").forEach(x=>x.onclick=()=>{tpsBlkDo(x.dataset.tb);r()})},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"coins",std:["2.MD.C.8"],msg:"The coin values chart supplies what each coin is worth, so the money items done with it show adding and the cent sign, not knowing the coins. Count them as supported, not independent."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into hundreds, tens, and ones for the student, so count the digit value and expanded form items as supported, not independent."},{t:"chart",std:["2.NBT.A.2"],msg:"The 120 chart shows the counting sequence, so counting and skip-counting items done with it are supported, not independent."},{t:"sent",msg:"Sentence starters supply the opening, the linking and time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
